insert into public.policies (key, topic, title, rule_text, value, client_visible, needs_confirmation, sort) values
  ('honesty.commitments', 'House rules', 'Honesty', 'Agents never make a commitment that isn''t in the policy book. Unknown → escalate to a human.', '{"escalate_unknown":true,"never_promise":["discounts","dates not confirmed on the calendar","inclusions not in the policy book","outcomes"]}'::jsonb, true, false, 10),
  ('pricing.phone', 'Sales', 'Pricing on calls', 'No prices quoted on the phone; invite the caller to visit. Out-of-town callers may get the approved "starting from" band plus the brochure and video tour on WhatsApp.', '{"quote_prices_on_phone":false,"invite_to_visit":true,"out_of_town_band":{"enabled":true,"starting_from_paise":null,"label":"Starting-from band (awaiting Prashanth''s approval)"},"local_cities":["Bengaluru","Bangalore","Devanahalli","Yelahanka","Hebbal","Hosakote","Doddaballapur"],"send_brochure":true,"send_video_tour":true}'::jsonb, false, true, 20),
  ('followup.after_visit', 'Sales', 'Follow-up', 'Exactly one follow-up call, two days after a site visit. No response = stop calling.', '{"calls":1,"days_after_visit":2,"stop_if_no_response":true}'::jsonb, false, false, 30),
  ('payments.schedule', 'Bookings', 'Payments', '10% deposit holds the date; 40% within two weeks signs the contract; 50% due 30 days before the event.', '{"milestones":[{"milestone":"deposit","label":"10% deposit — holds your date","percent_bps":1000,"due":"on_booking","effect":"holds_date"},{"milestone":"contract","label":"40% — signs the contract","percent_bps":4000,"due":"days_after_booking","days":14,"effect":"signs_contract"},{"milestone":"final","label":"50% — final payment","percent_bps":5000,"due":"days_before_event","days":30,"effect":"final"}],"reminder_offsets_days":[7,3,0]}'::jsonb, true, false, 40),
  ('contract.template', 'Bookings', 'Contract', 'Plain black-and-white template; e-signature.', '{"style":"plain_black_and_white","esign":true,"signer_for_venue":"Prashanth"}'::jsonb, true, false, 50),
  ('decor.providers', 'Planning', 'Décor', 'Only the in-house team or a designated planner. Venue provides infrastructure (power, complimentary rooms).', '{"allowed":["in_house","designated_planner"],"venue_provides":["power","complimentary rooms"],"requires_payment_unlock":"contract_paid"}'::jsonb, true, false, 60),
  ('moodboards', 'Planning', 'Moodboards', 'About five per function, broad themes first, then detail. Standard and custom labelled clearly.', '{"per_function":5,"sequence":["broad","detail"],"label_standard_vs_custom":true,"custom_needs_owner_approval":true}'::jsonb, true, false, 70),
  ('planning.start', 'Planning', 'Planning start', 'Recommended ~90 days before; the couple can start any stage earlier, but never before its payment unlock.', '{"recommended_days_before":90,"allow_early_start":true,"respect_payment_unlock":true}'::jsonb, true, false, 80),
  ('audit.portal_edits', 'Compliance', 'Audit', 'Every portal edit logs user, time and IP address.', '{"log_user":true,"log_time":true,"log_ip":true}'::jsonb, false, false, 90),
  ('reviews.after_event', 'After the wedding', 'Reviews', 'Personalised review form by email after each event; low scores reach Prashanth within 2 hours.', '{"channel":"email","personalised":true,"send_days_after_event":3,"low_score_threshold":3,"escalate_to_role":"owner","escalate_within_hours":2}'::jsonb, false, false, 100),
  ('farewell', 'After the wedding', 'Farewell', 'Thank-you note, parting gift (chocolates or an Amazon voucher), added to the newsletter.', '{"thank_you_note":true,"gift_options":["chocolates","amazon_voucher"],"gift_budget_paise":null,"add_to_newsletter":true,"referral_ask":true}'::jsonb, false, true, 110),
  ('discounts', 'Sales', 'Discounts', 'Agents never offer or promise a discount. Any discount request goes to Prashanth for a decision.', '{"agents_may_offer":false,"approver_role":"owner"}'::jsonb, false, false, 25),
  ('holds.soft_hold', 'Sales', 'Soft holds', 'A date can be held for 72 hours without payment. The hold releases automatically when it expires and the family is told.', '{"hours":72,"auto_release":true,"notify_client_on_release":true}'::jsonb, true, true, 35),
  ('portal.stage_cards', 'Planning', 'Portal stage cards', 'Each planning stage has a recommended start date. The couple can press Start early, but a stage never opens before its unlock condition. If a stage hasn''t started by its recommended date, the portal nudges once, then the event manager calls.', '{"cards":[{"key":"brief","name":"Our wedding (brief)","unlock":"deposit_paid","recommended_label":"On booking","triggers":"Brief agent guides the form; event manager assigned","needs_from_client":"Tell us about your functions, guests and rituals"},{"key":"ceremonies","name":"Ceremonies & schedule","unlock":"brief_started","recommended_days_before":120,"recommended_label":"120 days before","triggers":"Run-of-show draft","needs_from_client":"Confirm ceremony timings"},{"key":"menus","name":"Menus & tasting","unlock":"contract_paid","recommended_days_before":90,"recommended_label":"90 days before","triggers":"Menu options; tasting slot booking","needs_from_client":"Pick cuisines and book a tasting"},{"key":"decor","name":"Décor & moodboards","unlock":"contract_paid","recommended_days_before":90,"recommended_label":"90 days before","triggers":"About five moodboards per function","needs_from_client":"Shortlist your favourite moodboards"},{"key":"guests_rooms","name":"Guests & rooms","unlock":"contract_paid","recommended_days_before":60,"recommended_label":"60 days before","triggers":"Rooming list, pickup schedule","needs_from_client":"Share your rooming list and arrivals"},{"key":"vendors","name":"Vendors","unlock":"quote_approved","recommended_days_before":75,"recommended_label":"After décor and menu are final","triggers":"Vendor lock-in emails","needs_from_client":"Approve your quote"},{"key":"final_payment","name":"Final payment","unlock":"quote_approved","recommended_days_before":30,"recommended_label":"30 days before","triggers":"Invoice and payment link","needs_from_client":"Complete the final 50%"},{"key":"memories","name":"Memories","unlock":"event_complete","recommended_days_after":3,"recommended_label":"3 days after","triggers":"Photo sharing, review form, thank-you","needs_from_client":"Share your photos and tell us how we did"}],"nudge_once_then_call":true}'::jsonb, true, false, 85),
  ('lead_scoring', 'Sales', 'Lead scoring', 'Leads are scored 0–100 on date fit, guest count, budget signal and source. WedMeGood is weighted highest. Hot leads go straight to the sales executive.', '{"weights":{"date_fit":35,"guest_fit":20,"budget":20,"source":25},"source_scores":{"wedmegood":1,"referral":0.9,"walk_in":0.8,"website":0.7,"phone":0.7,"google_ads":0.6,"google_form":0.6,"instagram":0.6,"whatsapp":0.6,"manual":0.6,"meta_form":0.5,"facebook":0.5,"other":0.4},"ideal_guests":{"min":150,"max":300},"max_guests":800,"budget_bands_paise":{"low":150000000,"good":300000000,"premium":500000000},"hot_threshold":85}'::jsonb, false, false, 36),
  ('venue.facts', 'About Wiwaha', 'Venue facts', 'Wiwaha by Praman is a private 4-acre estate 15 km from Bengaluru airport with 30 guest rooms (expanding to 60), complimentary with a booking. Catering is in-house, or the family may bring their own caterer under the outside-caterer rules.', '{"estate_acres":4,"rooms_now":30,"rooms_planned":60,"airport_distance_km":15,"complimentary_rooms_with_booking":true,"catering":["South Indian","North Indian","Continental","Rajasthani","Pan-Asian"],"outside_caterer_allowed":true}'::jsonb, true, false, 5),
  ('visits.checklist', 'Sales', 'Site visit checklist', 'Every site visit is hosted in person by a uniformed executive, with refreshments ready, the space dressed and the brochure printed.', '{"items":[{"key":"uniform","label":"Executive in uniform"},{"key":"refreshments","label":"Refreshments ready"},{"key":"space_dressed","label":"Space dressed"},{"key":"brochure","label":"Brochure printed"}],"hosted_by":"sales executive"}'::jsonb, false, false, 32),
  ('briefs.schedule', 'Operations', 'Daily briefs', 'The morning brief goes out at 8:30 am and the evening review at 7 pm, India time.', '{"timezone":"Asia/Kolkata","morning":"08:30","evening":"19:00"}'::jsonb, false, false, 120),
  ('languages', 'About Wiwaha', 'Languages', 'The portal works in English with Hindi and Kannada options. The voice concierge also speaks Tamil and Telugu.', '{"portal":["en","kn","hi"],"voice":["en","kn","hi","ta","te"]}'::jsonb, false, true, 130)
insert into public.agents (key, name, vertical, job, human_gate, phase, implemented, enabled, autonomy, model) values
  ('chief_of_staff', 'Chief of Staff', 'all', 'Routes work between agents, writes Prashanth''s daily brief, watches SLAs', 'Prashanth sets priorities', 1, true, true, 'draft', 'claude-opus-5-5'),
  ('voice_concierge', 'Voice Concierge', 'sales_marketing', 'Answers and makes calls, books visits, one follow-up call', 'Live handover on request', 2, false, false, 'draft', 'claude-sonnet-5-5'),
  ('lead_desk', 'Lead Desk', 'sales_marketing', 'Unifies inbound channels, de-dupes, scores, replies', 'Hot leads to sales exec', 1, true, true, 'draft', 'claude-haiku-4-5'),
  ('visit_host', 'Visit Host', 'sales_marketing', 'Pre-visit brief, visit checklist, post-visit recap', 'Executive runs the visit', 2, false, false, 'draft', 'claude-sonnet-5-5'),
  ('content_studio', 'Content Studio', 'sales_marketing', 'Drafts posts, reels scripts, captions per weekly rhythm', 'Approve before posting', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('ads_analyst', 'Ads Analyst', 'sales_marketing', 'Tracks spend, cost per enquiry and per booking; proposes shifts', 'Budget changes approved', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('reputation', 'Reputation', 'sales_marketing', 'Review forms, Google/WedMeGood replies, testimonial capture', 'Low scores to Prashanth', 2, false, false, 'draft', 'claude-sonnet-5-5'),
  ('wedding_room', 'Wedding Room', 'event_crm', 'Lives in each WhatsApp group and portal; logs decisions, answers routine questions', 'Escalates anything off-policy', 3, false, false, 'draft', 'claude-sonnet-5-5'),
  ('onboarding', 'Onboarding', 'event_crm', 'Welcome letter, logins, portal walkthrough', 'None', 3, false, false, 'draft', 'claude-sonnet-5-5'),
  ('contract_payments', 'Contract & Payments', 'event_crm', 'Contract generation, 10/40/50 schedule, reminders, receipts', 'Prashanth signs contracts', 3, false, false, 'draft', 'claude-sonnet-5-5'),
  ('brief', 'Brief', 'event_crm', 'Guides the couple through ceremonies, guests, rituals', 'Event manager reviews', 3, false, false, 'draft', 'claude-sonnet-5-5'),
  ('design', 'Design', 'event_crm', '~5 moodboards per function, refines on feedback', 'Décor lead finalises; Prashanth for custom', 3, false, false, 'draft', 'claude-opus-5-5'),
  ('menu', 'Menu', 'event_crm', 'Menu options by cuisine, tasting booking, plate counts', 'Chef confirms', 3, false, false, 'draft', 'claude-sonnet-5-5'),
  ('quote', 'Quote', 'event_crm', 'Prices brief + décor + menu from price book', 'Off-book items to Prashanth', 3, false, false, 'draft', 'claude-opus-5-5'),
  ('vendor_coordinator', 'Vendor Coordinator', 'event_crm', 'Locks vendor dates, sends briefs, tracks confirmations, scores vendors', 'Vendor payments approved', 3, false, false, 'draft', 'claude-sonnet-5-5'),
  ('planner', 'Planner', 'operations', 'Builds T-minus plan and run-of-show from templates', 'Event manager signs off', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('standup', 'Stand-up', 'operations', '8:30 am and 7 pm briefs, chases overdue tasks', 'Escalates to manager', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('rooms_guests', 'Rooms & Guests', 'operations', 'Room allocation, rooming lists, pickups, housekeeping schedule', 'Front desk confirms', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('estate', 'Estate', 'operations', 'Maintenance schedule, inventory, utility readings', 'Purchases over limit approved', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('finance', 'Finance', 'operations', 'Final invoices, GST, reconciliation, per-wedding profit', 'Accounts reviews', 4, false, false, 'draft', 'claude-sonnet-5-5'),
  ('offboarding', 'Offboarding', 'operations', 'Thank-you, gift order, newsletter, referral ask, anniversaries', 'Gift budget approved once', 4, false, false, 'draft', 'claude-sonnet-5-5')
